// Napisy WebVTT/SRT -> czysty tekst
function subtitlesToText(s) {
  return String(s || '')
    .replace(/^WEBVTT.*$/m, '')
    .replace(/^\d+\s*$/gm, '')
    .replace(/^\s*\d{1,2}:\d{2}(:\d{2})?[.,]\d{3}\s*-->.*$/gm, '')
    .replace(/<[^>]+>/g, '')
    .replace(/\n{2,}/g, '\n')
    .split('\n').map((l) => l.trim()).filter(Boolean)
    .filter((l, i, arr) => l !== arr[i - 1])
    .join(' ')
    .trim();
