    if (u.hostname === 'youtu.be') return `https://youtube.com/watch?v=${u.pathname.slice(1)}`;
    if (u.pathname.length > 1 && u.pathname.endsWith('/')) u.pathname = u.pathname.replace(/\/+$/, '');
